actions.script:
if(!ec.user.isInGroup('ADMIN')){const error=new Error('Operator access required');error.moquiErrorKind='Unauthorized';throw error}
const old=ec.artifactExecution.disableAuthz()
try{const list=ec.entity.find('mantle.marketing.contact.ContactList').condition('contactListId',contactListId).one();if(!list || list.contactListTypeEnumId!=='MAILBOX')throw new Error('Mailbox not found');const category=ec.entity.find('mantle.forum.ForumCategory').condition('contactListId',contactListId).one();if(category?.publicationState==='published')throw new Error('Disable publication before conversion');runId=ec.user.randomString(32);const run=ec.entity.makeValue('mantle.forum.ForumJobRun');run.setFields({runId,siteId:category?.siteId || null,jobType:'bootstrap',state:'pending',checkpoint:JSON.stringify({contactListId}),createdAt:ec.user.nowTimestamp,successCount:0,failedCount:0},true,null,null);run.create()}finally{if(!old)ec.artifactExecution.enableAuthz()}
